draw:
var pad = 26;
var pipeW = (W - 3 * pad) / 2;
var v = 343;
var L = p.L;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function envelope(x0, yMid, width, amp, harmonic, closedRight) {
  ctx.strokeStyle = C.accent;
  for (var s = -1; s <= 1; s += 2) {
    ctx.beginPath();
    for (var i = 0; i <= 200; i++) {
      var u = i / 200;
      var shape = closedRight
        ? Math.cos(harmonic * Math.PI * u / 2)
        : Math.cos(harmonic * Math.PI * u);
      var x = x0 + width * u;
      var y = yMid - s * amp * shape;
      if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
    }
    ctx.stroke();
  }
}

var amp = H * 0.14;
var yA = H * 0.3;
var yB = H * 0.75;

// open-open pipe
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(pad, yA - amp - 10); ctx.lineTo(pad + pipeW, yA - amp - 10);
ctx.moveTo(pad, yA + amp + 10); ctx.lineTo(pad + pipeW, yA + amp + 10);
ctx.stroke();
envelope(pad, yA, pipeW, amp, p.n, false);

// closed-open pipe: closed at the right
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pad * 2 + pipeW, yB - amp - 10); ctx.lineTo(pad * 2 + 2 * pipeW, yB - amp - 10);
ctx.lineTo(pad * 2 + 2 * pipeW, yB + amp + 10);
ctx.lineTo(pad * 2 + pipeW, yB + amp + 10);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillRect(pad * 2 + 2 * pipeW - 6, yB - amp - 10, 6, 2 * amp + 20);
var odd = 2 * p.n - 1;
envelope(pad * 2 + pipeW, yB, pipeW, amp, odd, true);

ctx.fillStyle = C.ink;
var fOpen = p.n * v / (2 * L);
var fClosed = odd * v / (4 * L);
ctx.fillText("open at both ends, harmonic " + p.n, pad, yA - amp - 20);
ctx.fillText("antinode", pad - 4, yA + amp + 26);
ctx.fillText("antinode", pad + pipeW - 52, yA + amp + 26);
ctx.fillText("closed at one end, harmonic " + odd, pad * 2 + pipeW, yB - amp - 20);
ctx.fillText("antinode", pad * 2 + pipeW - 4, yB + amp + 26);
ctx.fillText("node", pad * 2 + 2 * pipeW - 34, yB + amp + 26);

out.note = "L = " + L.toFixed(2) + " m: open pipe " + fOpen.toFixed(0) + " Hz, stopped pipe " + fClosed.toFixed(0) + " Hz (odd harmonics only)";
